// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;

import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeLmdbQuerySource.NodeDomainSynopsis.RootCursor;
import org.junit.jupiter.api.Test;

class LmdbNodeDomainSynopsisTest {

	private static final int ROOT_COUNT = 100_000;
	private static final long PREDICATE = uri(10);
	private static final long MAXIMUM_SYNOPSIS_BYTES = 200_000L;

	@Test
	void densePresenceRanksOnlyExistingRootMultiplicities() throws IOException {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		try (LmdbInMemoryAdjacencyIndex base = LmdbPagedCsfBaseBuilder.build(new GappedIncomingScanner(),
				LmdbAdjacencyCoverage.full(), account, 1L << 20, 1L << 17)) {
			LmdbNodeDomainSynopsis synopsis = LmdbNodeDomainSynopsis.build(base,
					LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT, account, MAXIMUM_SYNOPSIS_BYTES);
			assertThat(synopsis)
					.as("a dense presence map must not reserve multiplicity lanes for absent ordinals")
					.isNotNull();
			try (synopsis) {
				assertThat(synopsis.cardinality()).isEqualTo(ROOT_COUNT);
				assertThat(synopsis.contains(uri(2L * (ROOT_COUNT - 1)))).isTrue();
				assertThat(synopsis.contains(uri(2L * ROOT_COUNT - 1L))).isFalse();

				RootCursor cursor = synopsis.cursor();
				assertThat(cursor.next()).isTrue();
				assertThat(cursor.rootId()).isEqualTo(uri(0));
				assertThat(cursor.quadMultiplicity()).isEqualTo(1000L);
				long rows = 1L;
				while (cursor.next()) {
					rows++;
					assertThat(cursor.quadMultiplicity()).isEqualTo(1L);
				}
				assertThat(rows).isEqualTo(ROOT_COUNT);
			}
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

	private static long uri(long ordinal) {
		return ValueIds.createId(ValueIds.T_URI, ordinal);
	}

	private static final class GappedIncomingScanner implements AdjacencySourceScanner {

		@Override
		public void scanPredicates(PredicateConsumer consumer) {
			consumer.predicate(PREDICATE);
		}

		@Override
		public void scanContexts(ContextConsumer consumer) {
		}

		@Override
		public void scanOutgoing(boolean explicit, GroupConsumer consumer) {
			if (!explicit) {
				return;
			}
			consumer.begin(uri(2L * ROOT_COUNT), PREDICATE, LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT);
			for (int row = 0; row < ROOT_COUNT + 999; row++) {
				consumer.pair(uri(3L * ROOT_COUNT + row), 0L);
			}
			consumer.end();
		}

		@Override
		public void scanIncoming(boolean explicit, GroupConsumer consumer) {
			if (!explicit) {
				return;
			}
			for (int root = 0; root < ROOT_COUNT; root++) {
				consumer.begin(uri(2L * root), PREDICATE, LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT);
				int multiplicity = root == 0 ? 1000 : 1;
				for (int row = 0; row < multiplicity; row++) {
					consumer.pair(uri(2L * ROOT_COUNT + row), 0L);
				}
				consumer.end();
			}
		}

		@Override
		public long snapshotRevision() {
			return 42L;
		}

		@Override
		public long snapshotId() {
			return 84L;
		}

		@Override
		public void ensureSnapshotValid() {
		}

		@Override
		public void close() {
		}
	}
}
